document.getElementById("registroForm").addEventListener("submit",(function(event){let isValid=!0;document.querySelectorAll(".error-message").forEach(el=>el.style.display="none"),document.querySelectorAll("input").forEach(el=>el.classList.remove("input-error"));const cedula=document.getElementById("cedula").value.trim(),nombres=document.getElementById("nombres_apellidos").value.trim(),telefono=document.getElementById("telefono").value.trim(),email=document.getElementById("email").value.trim(),youtube=document.getElementById("link_youtube").value.trim(),instagram=document.getElementById("perfil_instagram").value.trim();function showError(inputId,errorId,message){document.getElementById(inputId).classList.add("input-error");const errorSpan=document.getElementById(errorId);errorSpan.textContent=message,errorSpan.style.display="block",isValid=!1}const cedulaRegex=/^[0-9]{6,9}$/;cedula?cedulaRegex.test(cedula)||showError("cedula","error-cedula","Ingresa una cédula válida (solo números, entre 6 y 9 dígitos)."):showError("cedula","error-cedula","La cédula es obligatoria.");const nombresRegex=/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]{4,100}$/;nombres?nombresRegex.test(nombres)||showError("nombres_apellidos","error-nombres_apellidos","Ingresa un nombre válido (solo letras)."):showError("nombres_apellidos","error-nombres_apellidos","El nombre completo es obligatorio.");const telefonoRegex=/^[0-9]{10,15}$/;telefono?telefonoRegex.test(telefono)||showError("telefono","error-telefono","Ingresa un número telefónico válido (solo números, de 10 a 15 dígitos)."):showError("telefono","error-telefono","El teléfono es obligatorio.");const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;email?emailRegex.test(email)||showError("email","error-email","El formato del correo no es válido."):showError("email","error-email","El correo electrónico es obligatorio."),!youtube||youtube.includes("youtube.com")||youtube.includes("youtu.be")||showError("link_youtube","error-link_youtube","El enlace debe pertenecer a un dominio de YouTube."),instagram&&!instagram.includes("instagram.com")&&showError("perfil_instagram","error-perfil_instagram","El enlace debe pertenecer a un dominio de Instagram."),isValid||event.preventDefault()}));